const expected = String($vars.DOC_INTAKE_WEBHOOK_TOKEN || '').trim();
return { json: {
  ...root,
  auth_ok: Boolean(expected && provided && provided === expected),
  auth_reason: !expected ? 'missing_server_token_var' : !provided ? 'missing_token_header' : provided === expected ? '' : 'bad_token',
  checked_at: new Date().toISOString(),
} };

const crypto = require('crypto');
