}[ch]));
const filename = truncate(body.filename || body.file_name || 'unnamed-document', 180);
const mime_type = truncate(body.mime_type || body.mimeType || '', 120);
const attachment_id = truncate(body.attachment_id || body.attachmentId || '', 180);
const file_sha256_raw = String(body.file_sha256 || body.sha256 || '').toLowerCase();
const file_sha256_valid = /^[a-f0-9]{64}$/.test(file_sha256_raw);
const file_sha256 = file_sha256_valid ? file_sha256_raw : '';
const file_sha256_malformed = Boolean(file_sha256_raw && !file_sha256_valid);
const rawText = String(body.ocr_text || body.text || body.extracted_text || '');
