const supportedMime = ['application/pdf', 'image/png', 'image/jpeg', 'image/tiff', 'image/heic', 'text/plain'].includes(mime_type);
const errors = [];
if (!filename || filename === 'unnamed-document') errors.push('filename missing');
if (!supportedMime) errors.push('unsupported mime_type');
if (!attachment_id && !file_sha256) errors.push('attachment_id or file_sha256 required');
if (file_sha256_malformed) errors.push('file_sha256 must be 64 hex characters when provided');
