  { re: /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, token: '[email-redacted]' },
  { re: /\b[A-Za-z]{2}\d{2}(?:[ -]?[A-Za-z0-9]){11,30}\b/g, token: '[iban-redacted]' },
  { re: /\b(?:NIP[:\s-]*)?\d{3}[ -]?\d{3}[ -]?\d{2}[ -]?\d{2}\b/gi, token: '[tax-id-redacted]' },
  { re: /\b\d{11}\b/g, token: '[national-id-redacted]' },
