const redactedBody = redactForModel(rawText);
const redactedFilename = redactForModel(filename);
let modelText = redactedBody.text;
let filenameForModel = redactedFilename.text;
let pii_redacted_for_model = redactedBody.changed || redactedFilename.changed;
modelText = modelText.replace(/\s+/g, ' ').trim().slice(0, 6000);
filenameForModel = filenameForModel.replace(/\s+/g, ' ').trim().slice(0, 180);
const invalid_input = errors.length > 0 || !ocr_usable;
let status = 'AI Pending';
let review_reason = '';
let last_error_class = '';
let last_error_message = '';
if (errors.length > 0) {
  status = supportedMime ? 'Needs Review' : 'Dead Letter';
  review_reason = errors.join('; ');
  last_error_class = supportedMime ? 'business' : 'permanent';
  last_error_message = review_reason;
} else if (!ocr_usable) {
  status = 'Needs Review';
  review_reason = 'ocr_unusable: low confidence, too little text, or OCR garbage';
  last_error_class = 'business';
  last_error_message = review_reason;
}
return { json: {
  document_key,
  attachment_id,
  filename,
  filename_html: htmlEscape(filename),
  mime_type,
  file_sha256,
  status,
  document_type: '',
  party_name: '',
  party_name_html: '',
  document_date: '',
  amount_total: null,
  currency: 'Unknown',
  confidence: 0,
  validation_errors: errors.join('; '),
  review_reason,
  review_reason_html: htmlEscape(review_reason),
  archive_path: '',
  ocr_confidence: Number.isFinite(ocr_confidence) ? ocr_confidence : 0,
  scan_text_ratio: Number.isFinite(scan_text_ratio) ? scan_text_ratio : 0,
  model_transport_chars: modelText.length,
  pii_redacted_for_model,
  review_alert_sent: false,
  review_alert_id: '',
  ai_raw_json: '',
  model_prompt_excerpt: modelText.slice(0, 1200),
  ai_prompt_text: modelText,
  filename_for_model: filenameForModel,
  ocr_usable,
  invalid_input,
  raw_event_json: JSON.stringify({ source: body.source || '', attachment_id, filename, mime_type, file_sha256, ocr_confidence, scan_text_ratio, omitted_fields: ['sender_email', 'email_body', 'raw_ocr_text'] }).slice(0, 9000),
  last_execution_id: $execution.id,
  last_error_class,
  last_error_message,
  created_at: now,
  updated_at: now,
} };

