const base = $('Normalize Document Intake').item.json;
const raw = $input.item.json;
const extractText = (value) => {
  if (typeof value === 'string') return value;
  if (Array.isArray(value)) return value.map(extractText).filter(Boolean).join('\n');
  if (value && typeof value === 'object') {
    if (typeof value.text === 'string') return value.text;
    if (typeof value.output_text === 'string') return value.output_text;
    if (value.content) return extractText(value.content);
    if (value.output) return extractText(value.output);
  }
  return '';
};
let ai = raw.output ?? raw.text ?? raw.content ?? raw;
let parsedFrom = 'object';
if (typeof ai === 'string') {
  parsedFrom = 'string';
  const cleaned = ai.replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();
  try { ai = JSON.parse(cleaned); } catch { ai = null; }
} else {
  const extracted = extractText(ai);
  if (extracted) {
    const cleaned = extracted.replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();
    try { ai = JSON.parse(cleaned); parsedFrom = 'nested_text'; } catch { /* keep object */ }
  }
}
const allowedTypes = ['Invoice', 'Contract', 'Receipt', 'Other'];
const allowedCurrency = ['PLN', 'EUR', 'USD', 'GBP', 'Unknown'];
const reasons = [];
const warnings = [];
const htmlEscape = (value) => String(value ?? '').replace(/[&<>"']/g, ch => ({
  '&': '&amp;',
  '<': '&lt;',
  '>': '&gt;',
  '"': '&quot;',
  "'": '&#39;',
}[ch]));
if (!ai || typeof ai !== 'object' || Array.isArray(ai)) reasons.push('AI output unparseable or not an object');
ai = ai && typeof ai === 'object' && !Array.isArray(ai) ? ai : {};
const enumPick = (value, allowed, fallback, label) => {
  const v = typeof value === 'string' ? value.trim() : '';
  if (allowed.includes(v)) return v;
  reasons.push(label + ' outside closed enum');
  return fallback;
};
const clamp01 = (value, label) => {
  let n = Number(value);
  if (!Number.isFinite(n)) {
    reasons.push(label + ' missing or nonnumeric');
    n = 0;
  }
  return Math.max(0, Math.min(1, n));
};
const document_type = enumPick(ai.document_type, allowedTypes, 'Other', 'document_type');
const currency = enumPick(ai.currency || 'Unknown', allowedCurrency, 'Unknown', 'currency');
const confidence = clamp01(ai.confidence, 'confidence');
const fc = ai.field_confidence && typeof ai.field_confidence === 'object' ? ai.field_confidence : {};
const typeConfidence = clamp01(fc.document_type ?? confidence, 'field_confidence.document_type');
const partyConfidence = clamp01(fc.party_name ?? confidence, 'field_confidence.party_name');
const dateConfidence = clamp01(fc.document_date ?? confidence, 'field_confidence.document_date');
const amountConfidence = clamp01(fc.amount_total ?? confidence, 'field_confidence.amount_total');
const party_name = typeof ai.party_name === 'string' ? ai.party_name.replace(/\s+/g, ' ').trim().slice(0, 140) : '';
if (party_name.length < 2) reasons.push('party_name missing or too short');
let document_date = typeof ai.document_date === 'string' ? ai.document_date.trim() : '';
if (document_date && !/^\d{4}-\d{2}-\d{2}$/.test(document_date)) {
  reasons.push('document_date not YYYY-MM-DD');
  document_date = '';
}
if (document_date) {
  const d = new Date(document_date + 'T00:00:00Z');
  if (!Number.isNaN(d.getTime()) && d.toISOString().slice(0, 10) !== document_date) {
    reasons.push('document_date not a real calendar date');
    document_date = '';
  }
  const min = new Date('1990-01-01T00:00:00Z');
  const max = new Date(Date.now() + 366 * 24 * 60 * 60 * 1000);
  if (Number.isNaN(d.getTime()) || d < min || d > max) {
    reasons.push('document_date outside sane range');
    document_date = '';
  }
}
if (!document_date) reasons.push('document_date missing');
let amount_total = ai.amount_total === null || ai.amount_total === undefined || ai.amount_total === '' ? null : Number(ai.amount_total);
if (amount_total !== null && (!Number.isFinite(amount_total) || amount_total < 0 || amount_total > 10000000)) {
  reasons.push('amount_total outside sane range');
  amount_total = null;
}
if ((document_type === 'Invoice' || document_type === 'Receipt') && amount_total === null) reasons.push('amount_total required for Invoice/Receipt');
if (document_type === 'Contract' && amount_total === null) warnings.push('amount_total missing for Contract; allowed as incomplete non-filing field');
if (document_type === 'Other') reasons.push('document_type Other requires human review');
if (confidence < 0.45) reasons.push('very low confidence');
if ((document_type === 'Invoice' || document_type === 'Receipt') && currency === 'Unknown') reasons.push('currency required for Invoice/Receipt');
if (base.status && base.status !== 'AI Pending') reasons.push('intake status not eligible for auto-file: ' + base.status);
if (base.validation_errors) reasons.push('intake validation errors: ' + String(base.validation_errors).slice(0, 300));
const reviewReason = [
  typeof ai.review_reason === 'string' ? ai.review_reason.trim().slice(0, 500) : '',
  ...reasons,
  ...warnings,
].filter(Boolean).join('; ');
const criticalReasons = reasons.length > 0;
const amountConfidenceOk = document_type === 'Contract' && amount_total === null ? true : amountConfidence >= 0.75;
const auto_file = !criticalReasons && confidence >= 0.82 && typeConfidence >= 0.8 && partyConfidence >= 0.75 && dateConfidence >= 0.75 && amountConfidenceOk && (amount_total !== null || document_type === 'Contract') && ai.needs_human_review !== true;
const safeParty = (party_name || 'unknown-party').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 60) || 'unknown-party';
const safeFilename = (base.filename || 'document').toLowerCase().replace(/[^a-z0-9._-]+/g, '-').replace(/\.{2,}/g, '.').replace(/^[.-]+|[.-]+$/g, '').slice(0, 100) || 'document';
const year = document_date ? document_date.slice(0, 4) : 'unknown-year';
const shortKey = base.document_key.slice(0, 12);
const archiveName = (document_date || 'unknown-date') + '__' + safeParty + '__' + shortKey + '__' + safeFilename;
const reviewName = shortKey + '__' + safeFilename;
const archive_path = auto_file
  ? ['archive', document_type, year, archiveName].join('/')
  : ['review', document_type || 'Other', reviewName].join('/');
const finalReviewReason = auto_file ? warnings.join('; ') : reviewReason;
return { json: {
  ...base,
  status: auto_file ? 'Filed' : 'Needs Review',
  document_type,
  party_name,
  filename_html: htmlEscape(base.filename),
  party_name_html: htmlEscape(party_name),
  document_date,
  amount_total,
  currency,
  confidence,
  validation_errors: reasons.join('; '),
  review_reason: finalReviewReason,
  review_reason_html: htmlEscape(finalReviewReason),
  archive_path,
  review_alert_sent: false,
  review_alert_id: '',
  ai_raw_json: JSON.stringify({ parsedFrom, ai }).slice(0, 9000),
  last_error_class: auto_file ? '' : 'business',
  last_error_message: auto_file ? '' : reviewReason,
  auto_file,
  updated_at: new Date().toISOString(),
} };

